//! Exact-output tests for the port of D2 v0.9.0's embedded-font pipeline
//! (`d2fonts.Font.GetEncodedSubset` -> `font.UTF8CutFont` -> `font.Sfnt2Woff`).
//!
//! Fixtures (oracle tier, regenerated by recipe `mathtext-txt-font-subset`,
//! which builds `tools/font-subset-oracle` against the pinned upstream tree):
//!
//! * `fixtures/font_subset/oracle_cases.json`: every bundled family/style
//!   registration times 15 corpora (empty, ASCII, duplicates, Latin-1/
//!   extended, CJK, emoji/astral, combining marks, controls/NUL, U+FFFF and
//!   private use), with SHA-256 of Go's `UTF8CutFont` output, `Sfnt2Woff`
//!   output and `GetEncodedSubset` data URI. Produced by
//!   `font-subset-oracle cases`.
//! * `fixtures/font_subset/golden_fonts.json`: every unique subset font
//!   embedded in `../d2/e2etests/testdata/**/*.exp.svg` (518 fonts), with
//!   the character set recovered from its cmap, the digest of the golden data
//!   URI and of Go's cut font. Produced by `font-subset-oracle golden`, which
//!   checks that Go's pipeline reproduces each golden. For the 13 entries
//!   flagged `golden_zlib_differs` the golden's decompressed WOFF matches
//!   while its zlib bytes predate the pinned encoder; their `uri_sha256` is
//!   the pinned pipeline's output.

#![cfg_attr(not(feature = "oracle-fixtures"), allow(dead_code, unused_imports))]

use std::io::Read as _;

use d2_rs_text::d2fonts::{
    FONT_FAMILIES, FONT_STYLES, Font, FontFamily, FontStyle, font_encoding, font_face, unique_chars,
};
use d2_rs_text::subset_font::utf8_cut_font;
use d2_rs_text::woff::sfnt2woff_with;
use serde::Deserialize;
use sha2::{Digest, Sha256};

#[derive(Deserialize)]
struct OracleCase {
    family: String,
    style: String,
    corpus: String,
    cut_sha256: String,
    woff_sha256: String,
    uri_sha256: String,
}

#[derive(Deserialize)]
struct GoldenFont {
    family: String,
    style: String,
    chars: String,
    cut_sha256: String,
    uri_sha256: String,
    #[serde(default)]
    golden_zlib_differs: bool,
}

fn hex_digest(data: &[u8]) -> String {
    Sha256::digest(data)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn font(family: &str, style: &str) -> Font {
    let family = FONT_FAMILIES
        .into_iter()
        .find(|f| f.as_str() == family)
        .unwrap_or_else(|| panic!("unknown family {family}"));
    let style = FONT_STYLES
        .into_iter()
        .find(|s| s.as_str() == style)
        .unwrap_or_else(|| panic!("unknown style {style}"));
    family.font(style)
}

#[cfg(feature = "oracle-fixtures")]
fn oracle_cases() -> Vec<OracleCase> {
    serde_json::from_str(d2_rs_testdata::oracle_fixture!("tests/fixtures/font_subset/oracle_cases.json")).unwrap()
}

#[cfg(feature = "oracle-fixtures")]
fn golden_fonts() -> Vec<GoldenFont> {
    serde_json::from_str(d2_rs_testdata::oracle_fixture!("tests/fixtures/font_subset/golden_fonts.json")).unwrap()
}

#[test]
fn custom_families_select_each_style_and_use_sans_fallbacks() {
    use d2_rs_text::d2fonts::CustomFonts;
    let mut fonts = CustomFonts::default();
    assert_eq!(
        fonts.get_encoded_subset(false, FontStyle::Bold, "abc"),
        Ok(None)
    );
    for style in FONT_STYLES {
        fonts.regular.insert(
            style,
            font_face(FontFamily::SourceCodePro.font(style)).to_vec(),
        );
        fonts
            .mono
            .insert(style, font_face(FontFamily::HandDrawn.font(style)).to_vec());
    }
    for style in FONT_STYLES {
        for (mono, family) in [
            (false, FontFamily::SourceCodePro),
            (true, FontFamily::HandDrawn),
        ] {
            assert_eq!(
                fonts.get_encoded_subset(mono, style, "abc").unwrap(),
                family.font(style).get_encoded_subset("abc")
            );
        }
    }
    fonts.regular.remove(&FontStyle::Italic);
    fonts.mono.remove(&FontStyle::Italic);
    let fallback = FontFamily::SourceSansPro
        .font(FontStyle::Italic)
        .get_encoded_subset("abc");
    assert_eq!(
        fonts
            .get_encoded_subset(false, FontStyle::Italic, "abc")
            .unwrap(),
        fallback
    );
    assert_eq!(
        fonts
            .get_encoded_subset(true, FontStyle::Italic, "abc")
            .unwrap(),
        fallback
    );
}

/// Any valid zlib stream; the WOFF container is independent of the encoder.
fn reference_zlib(data: &[u8]) -> Vec<u8> {
    use std::io::Write as _;
    let mut encoder = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
    encoder.write_all(data).unwrap();
    encoder.finish().unwrap()
}

