#[test]
fn unique_chars_keeps_first_appearance_order() {
    assert_eq!(
        unique_chars("abcabc ba\u{1F600}a\u{1F600}"),
        "abc \u{1F600}"
    );
    assert_eq!(unique_chars(""), "");
}

#[cfg(feature = "oracle-fixtures")]
#[test]
fn every_registration_and_corpus_class_is_covered() {
    let cases = oracle_cases();
    assert_eq!(cases.len(), FONT_FAMILIES.len() * FONT_STYLES.len() * 15);
    for family in FONT_FAMILIES {
        for style in FONT_STYLES {
            let count = cases
                .iter()
                .filter(|c| c.family == family.as_str() && c.style == style.as_str())
                .count();
            assert_eq!(count, 15, "{family:?} {style:?}");
        }
    }
    assert!(cases.iter().any(|c| c.corpus.is_empty()));
    assert!(cases.iter().any(|c| c.corpus.contains('中')));
    assert!(cases.iter().any(|c| c.corpus.contains('\u{1F600}')));
    assert!(cases.iter().any(|c| c.corpus.contains("aaaa")));
}

#[cfg(feature = "oracle-fixtures")]
#[test]
fn utf8_cut_font_matches_go_oracle_cases() {
    let cases = oracle_cases();
    let mut mismatches = Vec::new();
    for case in &cases {
        let face = font_face(font(&case.family, &case.style));
        let cut = utf8_cut_font(face, &unique_chars(&case.corpus)).expect("bundled faces cut");
        if hex_digest(&cut) != case.cut_sha256 {
            mismatches.push(format!("{} {} {:?}", case.family, case.style, case.corpus));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} differ: {mismatches:#?}",
        mismatches.len(),
        cases.len()
    );
}

#[cfg(feature = "oracle-fixtures")]
#[test]
fn utf8_cut_font_matches_every_upstream_golden_font() {
    let goldens = golden_fonts();
    assert_eq!(goldens.len(), 518);
    let mut mismatches = Vec::new();
    for golden in &goldens {
        let face = font_face(font(&golden.family, &golden.style));
        let cut = utf8_cut_font(face, &golden.chars).expect("bundled faces cut");
        if hex_digest(&cut) != golden.cut_sha256 {
            mismatches.push(format!(
                "{} {} {:?}",
                golden.family, golden.style, golden.chars
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} differ: {mismatches:#?}",
        mismatches.len(),
        goldens.len()
    );
}

/// Decodes a WOFF written by `Sfnt2Woff` back into the SFNT it encodes,
/// laying tables out in directory order exactly as `assembleTables` does.
fn decode_woff_to_sfnt(woff: &[u8], original: &[u8]) -> Vec<u8> {
    let be16 = |b: &[u8], at: usize| u16::from_be_bytes([b[at], b[at + 1]]);
    let be32 = |b: &[u8], at: usize| u32::from_be_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]]);
    assert_eq!(be32(woff, 0), 0x774f_4646);
    assert_eq!(be32(woff, 8) as usize, woff.len());
    let num_tables = be16(woff, 12) as usize;
    assert_eq!(be16(original, 4) as usize, num_tables);
    let mut sfnt = original[..12 + num_tables * 16].to_vec();
    let mut previous_tag = [0_u8; 4];
    for i in 0..num_tables {
        let entry = &woff[44 + i * 20..64 + i * 20];
        let tag: [u8; 4] = entry[..4].try_into().unwrap();
        assert!(i == 0 || tag > previous_tag, "directory sorted by tag");
        previous_tag = tag;
        let offset = be32(entry, 4) as usize;
        let comp_length = be32(entry, 8) as usize;
        let length = be32(entry, 12) as usize;
        assert_eq!(offset % 4, 0);
        assert_eq!(&original[12 + i * 16..16 + i * 16], &tag);
        assert_eq!(
            &entry[16..20],
            &original[16 + i * 16..20 + i * 16],
            "checksum"
        );
        assert_eq!(be32(&original, 24 + i * 16) as usize, length);
        let payload = &woff[offset..offset + comp_length];
        let mut data = if comp_length < length {
            let mut out = Vec::new();
            flate2::read::ZlibDecoder::new(payload)
                .read_to_end(&mut out)
                .unwrap();
            out
        } else {
            assert_eq!(comp_length, length);
            payload.to_vec()
        };
        assert_eq!(data.len(), length);
        assert_eq!(be32(&original, 20 + i * 16) as usize, sfnt.len());
        data.resize(length.div_ceil(4) * 4, 0);
        sfnt.extend_from_slice(&data);
    }
    // header: flavor is the head table version, versions the font revision.
    let head_dir = (0..num_tables)
        .find(|&i| &original[12 + i * 16..16 + i * 16] == b"head")
        .unwrap();
    let head = be32(&original, 20 + head_dir * 16) as usize;
    assert_eq!(&woff[4..8], &original[head..head + 4]);
    assert_eq!(&woff[20..24], &original[head + 4..head + 8]);
    assert_eq!(be32(woff, 16) as usize, original.len());
    sfnt
}

/// `Sfnt2Woff` rewrites `head.checkSumAdjustment` with the standard
/// `0xB1B0AFBA - sum` value. `assembleTables`' `calcInt32` increments the
/// high word on a low-word borrow instead of decrementing it, so the cut
/// font's own value can be off by 2 << 16.
fn with_correct_checksum_adjustment(sfnt: &[u8]) -> Vec<u8> {
    let num_tables = u16::from_be_bytes([sfnt[4], sfnt[5]]) as usize;
    let head = (0..num_tables)
        .find(|&i| &sfnt[12 + i * 16..16 + i * 16] == b"head")
        .map(|i| u32::from_be_bytes(sfnt[20 + i * 16..24 + i * 16].try_into().unwrap()) as usize)
        .unwrap();
    let mut fixed = sfnt.to_vec();
    fixed[head + 8..head + 12].fill(0);
    let sum = fixed
        .chunks_exact(4)
        .map(|w| u32::from_be_bytes(w.try_into().unwrap()))
        .fold(0_u32, u32::wrapping_add);
    fixed[head + 8..head + 12].copy_from_slice(&0xB1B0_AFBA_u32.wrapping_sub(sum).to_be_bytes());
    fixed
}

#[cfg(feature = "oracle-fixtures")]
#[test]
fn sfnt2woff_container_round_trips_every_oracle_cut() {
    for case in oracle_cases() {
        let face = font_face(font(&case.family, &case.style));
        let original_cut = utf8_cut_font(face, &unique_chars(&case.corpus)).unwrap();
        let cut = original_cut.clone();
        // Go validates every non-head checksum and never takes the
        // FontEncodings fallback for the bundled faces.
        let woff = sfnt2woff_with(&cut, reference_zlib).expect("no checksum fallback");
        let decoded = decode_woff_to_sfnt(&woff, &cut);
        let cut = with_correct_checksum_adjustment(&cut);
        assert_eq!(
            decoded
                .iter()
                .zip(&cut)
                .position(|(a, b)| a != b)
                .map(|at| (at, decoded.len(), cut.len())),
            None,
            "{} {} {:?}",
            case.family,
            case.style,
            case.corpus
        );
        assert_eq!(decoded, cut);

        // Storing every table (Go's choice when deflate does not shrink it).
        let stored = sfnt2woff_with(&original_cut, |data| {
            let mut grown = data.to_vec();
            grown.push(0);
            grown
        })
        .unwrap();
        assert_eq!(decode_woff_to_sfnt(&stored, &cut), cut);
        assert_ne!(stored, woff);
        let num_tables = u16::from_be_bytes([cut[4], cut[5]]) as usize;
        let mut expected_len = 44 + 20 * num_tables;
        for i in 0..num_tables {
            let entry = &stored[44 + i * 20..64 + i * 20];
            assert_eq!(entry[8..12], entry[12..16], "stored table keeps its length");
            expected_len +=
                (u32::from_be_bytes(entry[12..16].try_into().unwrap()) as usize).div_ceil(4) * 4;
        }
        assert_eq!(stored.len(), expected_len);
    }
}

#[test]
fn sfnt2woff_rejects_a_corrupted_table_checksum() {
    let face = font_face(FontFamily::SourceSansPro.font(FontStyle::Regular));
    let mut cut = utf8_cut_font(face, "abc").unwrap();
    let last = cut.len() - 1;
    cut[last] ^= 0xFF;
    assert!(matches!(
        sfnt2woff_with(&cut, reference_zlib),
        Err(d2_rs_text::woff::Sfnt2WoffError::Checksum { .. })
    ));
}

#[cfg(feature = "oracle-fixtures")]
#[test]
fn get_encoded_subset_matches_go_oracle_cases() {
    let cases = oracle_cases();
    let mut mismatches = Vec::new();
    for case in &cases {
        let woff = d2_rs_text::woff::sfnt2woff(
            &utf8_cut_font(
                font_face(font(&case.family, &case.style)),
                &unique_chars(&case.corpus),
            )
            .unwrap(),
        )
        .unwrap();
        let uri = font(&case.family, &case.style)
            .get_encoded_subset(&case.corpus)
            .unwrap();
        if hex_digest(&woff) != case.woff_sha256 || hex_digest(uri.as_bytes()) != case.uri_sha256 {
            mismatches.push(format!("{} {} {:?}", case.family, case.style, case.corpus));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} differ: {mismatches:#?}",
        mismatches.len(),
        cases.len()
    );
}

#[cfg(feature = "oracle-fixtures")]
#[test]
fn get_encoded_subset_reproduces_every_upstream_golden_font() {
    let goldens = golden_fonts();
    let mut mismatches = Vec::new();
    for golden in &goldens {
        let uri = font(&golden.family, &golden.style)
            .get_encoded_subset(&golden.chars)
            .unwrap();
        if hex_digest(uri.as_bytes()) != golden.uri_sha256 {
            mismatches.push(format!(
                "{} {} {:?} zlib_differs={}",
                golden.family, golden.style, golden.chars, golden.golden_zlib_differs
            ));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} of {} differ: {mismatches:#?}",
        mismatches.len(),
        goldens.len()
    );
}
